WITH active AS (SELECT series_id FROM public.paper_series WHERE status='active'), observed AS (SELECT statement_timestamp() AS read_at), selected AS (SELECT e.event_id,e.series_id,e.revision,e.candidate_id,e.pair,e.phase,e.result,e.source_known_at,e.received_at,e.payload->>'event_time_utc' AS event_time_utc,e.payload->'data'->'p4_decision' AS p4_decision,e.payload->'data'->'paper_entry_ask_eur' AS paper_entry_ask_eur,e.payload->'data'->'paper_entry_qty' AS paper_entry_qty,e.payload->'data'->'paper_entry_fee_eur' AS paper_entry_fee_eur,e.payload->'data'->'paper_exit_bid_eur' AS paper_exit_bid_eur,e.payload->'data'->'paper_exit_fee_eur' AS paper_exit_fee_eur,e.payload->'data'->'position_net_pnl_eur' AS position_net_pnl_eur,e.payload->'data'->'position_net_return_pct' AS position_net_return_pct,e.payload->'data'->'followup_source' AS followup_source,e.payload->'data'->'path_contiguous_1m_verified' AS path_contiguous_1m_verified,e.payload->'data'->'source_status' AS source_status,e.payload->'data'->'mfe_pct' AS mfe_pct,e.payload->'data'->'mae_pct' AS mae_pct,e.payload->'data'->'close_return_pct' AS close_return_pct,e.payload->'data'->'censor_reason' AS censor_reason FROM public.v3_paper_event_receipts e JOIN active a ON e.series_id=a.series_id CROSS JOIN observed o WHERE e.received_at<=o.read_at) SELECT o.read_at,(SELECT count(*) FROM active) AS active_count,(SELECT min(series_id) FROM active) AS series_id,(SELECT count(*) FROM selected) AS exact_count,(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) FROM (SELECT * FROM selected ORDER BY source_known_at,received_at,event_id LIMIT 5000) q) AS rows FROM observed o;
